def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != bg for v in row) for row in grid]

    # Find the vertical offset aligning the two repeated patterns.
    best_d, best_score, best_pairs = 0, 0, []
    for d in range(1, h):
        pairs = [(r, r + d) for r in range(h - d)
                 if active[r] and active[r + d]]
        score = sum(
            grid[r][c] == grid[s][c] and grid[r][c] != bg
            for r, s in pairs for c in range(w)
        )
        if score > best_score:
            best_d, best_score, best_pairs = d, score, pairs

    if not best_d or not best_pairs:
        return [row[:] for row in grid]

    upper_count = sum(sum(v != bg for v in grid[r]) for r, _ in best_pairs)
    lower_count = sum(sum(v != bg for v in grid[s]) for _, s in best_pairs)

    out = [row[:] for row in grid]
    if upper_count < lower_count:
        for r, s in best_pairs:
            for c in range(w):
                if grid[s][c] != bg and out[r][c] == bg:
                    out[r][c] = 1
    elif lower_count < upper_count:
        for r, s in best_pairs:
            for c in range(w):
                if grid[r][c] != bg and out[s][c] == bg:
                    out[s][c] = 1

    return out
